    visited = set()
    for start in cells:
        if start in visited:
            continue
        component = []
        queue = [start]
        visited.add(start)
        while queue:
            r, c = queue.pop(0)
            component.append((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr, nc) not in visited and g[nr][nc] == color:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        components.append(component)
    return components

def is_bar(comp):
    rows = [c[0] for c in comp]
    cols = [c[1] for c in comp]
    span_r = max(rows) - min(rows)
    span_c = max(cols) - min(cols)
    return span_r >= 1 or span_c >= 1

def is_horizontal_bar(comp):
    rows = [c[0] for c in comp]
    return len(set(rows)) == 1

